def readouts(items):
    return '<div class="lab-readouts">' + "".join(
        f'<div><span>{label}</span><strong id="{rid}">—</strong></div>' for label, rid in items) + "</div>"


def section(p, controls, display, business, method):
    return (
        f'<section class="lab-experiment c-sec" id="{p["section"]}" aria-labelledby="{p["section"]}-heading"><div class="c-wrap">'
        f'<div class="lab-section-heading"><span>{p["num"]}</span><div><p class="c-kicker">{p["sec_kicker"]}</p>'
        f'<h2 id="{p["section"]}-heading">{p["sec_h2"]}</h2><p class="lab-what"><strong>What this shows:</strong> {p["what"]}</p>@@OPEN@@</div></div>'
        f'<div class="lab-grid"><div class="lab-controls">{controls}<button class="lab-text-button" id="reset-{p["section"]}" type="button">Reset this experiment</button></div>'
        f'<div class="lab-display">{display}{FLAG}</div></div>'
        f'<div class="lab-business"><strong>Where this matters</strong><p>{business}</p></div>'
        f'<details class="lab-method"><summary>What this experiment models</summary><p>{method}</p></details></div></section>'
    )


def svg(sid, height, title):
    return (f'<svg id="{sid}" class="ml-wide" viewBox="0 0 720 {height}" role="img" aria-labelledby="{sid}-title {sid}-desc">'
            f'<title id="{sid}-title">{title}</title><desc id="{sid}-desc">{title}.</desc></svg>')


